using System.Collections.ObjectModel;using System.Windows;using System.Windows.Controls;using SaarOSS.Rechnungsprogramm.Models;using SaarOSS.Rechnungsprogramm.Services;
namespace SaarOSS.Rechnungsprogramm.Views;
public partial class OffersView:UserControl
{
 readonly OfferService _service=new();readonly TaxProfileService _taxService=new();readonly DocumentDesignService _designService=new();readonly InvoiceService _invoiceService=new();OfferStore _store=new();InvoiceStore _invoices=new();Offer _current=new();ObservableCollection<InvoiceLine> _lines=new();List<CustomerChoice> _customers=new();
 public OffersView(){InitializeComponent();_current=NewModel();LoadAll();LoadForm(_current);}Offer NewModel(){var p=_taxService.Load();var d=_designService.CreateSnapshot();return new(){TaxModeSnapshot=p.TaxMode,SmallBusinessNoticeSnapshot=p.IsSmallBusiness?p.SmallBusinessNotice:"",ShowLogoSnapshot=d.ShowLogo,LogoPngBase64Snapshot=d.LogoPngBase64,HeaderLine1Snapshot=d.HeaderLine1,HeaderLine2Snapshot=d.HeaderLine2,HeaderLine3Snapshot=d.HeaderLine3,HeaderLine4Snapshot=d.HeaderLine4,Lines=new(){new InvoiceLine{VatRate=p.IsSmallBusiness?0m:19m}}};}
 void LoadAll(){try{_store=_service.Load();_invoices=_invoiceService.LoadInvoices();_customers=_invoiceService.LoadCustomers();CustomerBox.ItemsSource=_customers;RefreshNumberingUi();RefreshList();}catch(Exception ex){MessageBox.Show(ex.Message,"Angebote",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void RefreshList(){OfferList.ItemsSource=null;OfferList.ItemsSource=_store.Offers.OrderByDescending(x=>x.UpdatedAt).ToList();}void RefreshNumberingUi(){PrefixBox.Text=_store.Prefix;DigitsBox.Text=_store.Digits.ToString();NextBox.Text=_store.NextNumber.ToString();YearBox.IsChecked=_store.IncludeYear;UpdateNumberPreview();}
 void ToggleNumbering(object s,RoutedEventArgs e){NumberingCard.Visibility=NumberingCard.Visibility==Visibility.Visible?Visibility.Collapsed:Visibility.Visible;UpdateNumberPreview();}void UpdateNumberPreview(){if(int.TryParse(NextBox.Text,out var n)&&int.TryParse(DigitsBox.Text,out var d))NumberPreview.Text=$"Vorschau: {PrefixBox.Text.Trim()}{(YearBox.IsChecked==true?DateTime.Today.Year+"-":"")}{n.ToString().PadLeft(d,'0')}";}
 void SaveNumbering(object s,RoutedEventArgs e){if(!int.TryParse(DigitsBox.Text,out var d)||!int.TryParse(NextBox.Text,out var n)){MessageBox.Show("Bitte gültige Zahlen eingeben.");return;}try{_service.SaveNumbering(_store,PrefixBox.Text,YearBox.IsChecked==true,d,n);UpdateNumberPreview();MessageBox.Show("Angebotsnummernkreis gespeichert.");}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void LoadForm(Offer o){_current=Clone(o);_lines=new(_current.Lines);LineGrid.ItemsSource=_lines;CustomerBox.SelectedItem=_customers.FirstOrDefault(x=>x.Id==_current.CustomerId);OfferDateBox.SelectedDate=_current.OfferDate;ValidUntilBox.SelectedDate=_current.ValidUntil;IntroBox.Text=_current.IntroText;ClosingBox.Text=_current.ClosingText;EditorTitle.Text=_current.DisplayNumber;OfferNumberText.Text=_current.DisplayNumber;StatusText.Text=$"Status: {_current.Status}";UpdateTotals();ApplyState();}
 void ApplyState(){var edit=_current.Status=="Entwurf";VatColumn.IsReadOnly=_current.IsSmallBusinessSnapshot;VatColumn.Header=_current.IsSmallBusinessSnapshot?"USt. (gesperrt)":"USt. %";if(_current.IsSmallBusinessSnapshot)foreach(var line in _lines)line.VatRate=0m;EditorPanel.IsEnabled=edit;SaveButton.Visibility=edit?Visibility.Visible:Visibility.Collapsed;FinalizeButton.Visibility=edit&&_current.DraftNumber>0?Visibility.Visible:Visibility.Collapsed;PreviewButton.Visibility=!edit?Visibility.Visible:Visibility.Collapsed;AcceptButton.Visibility=_current.Status=="Versendet"?Visibility.Visible:Visibility.Collapsed;RejectButton.Visibility=_current.Status=="Versendet"?Visibility.Visible:Visibility.Collapsed;InvoiceButton.Visibility=_current.Status=="Angenommen"&&_current.CreatedInvoiceId is null?Visibility.Visible:Visibility.Collapsed;}
 static Offer Clone(Offer x)=>new(){Id=x.Id,DraftNumber=x.DraftNumber,OfferNumber=x.OfferNumber,CustomerId=x.CustomerId,CustomerNumber=x.CustomerNumber,CustomerName=x.CustomerName,CustomerAddressSnapshot=x.CustomerAddressSnapshot,CompanySnapshot=x.CompanySnapshot,TaxModeSnapshot=x.TaxModeSnapshot,SmallBusinessNoticeSnapshot=x.SmallBusinessNoticeSnapshot,ShowLogoSnapshot=x.ShowLogoSnapshot,LogoPngBase64Snapshot=x.LogoPngBase64Snapshot,HeaderLine1Snapshot=x.HeaderLine1Snapshot,HeaderLine2Snapshot=x.HeaderLine2Snapshot,HeaderLine3Snapshot=x.HeaderLine3Snapshot,HeaderLine4Snapshot=x.HeaderLine4Snapshot,OfferDate=x.OfferDate,ValidUntil=x.ValidUntil,IntroText=x.IntroText,ClosingText=x.ClosingText,InternalNote=x.InternalNote,Status=x.Status,FinalizedAt=x.FinalizedAt,SentAt=x.SentAt,AcceptedAt=x.AcceptedAt,RejectedAt=x.RejectedAt,CreatedInvoiceId=x.CreatedInvoiceId,UpdatedAt=x.UpdatedAt,Lines=x.Lines.Select(y=>new InvoiceLine{Description=y.Description,Quantity=y.Quantity,Unit=y.Unit,UnitPrice=y.UnitPrice,VatRate=y.VatRate,DiscountPercent=y.DiscountPercent}).ToList()};
 void NewOffer(object s,RoutedEventArgs e){OfferList.SelectedItem=null;LoadForm(NewModel());}void OfferSelected(object s,SelectionChangedEventArgs e){if(OfferList.SelectedItem is Offer o)LoadForm(o);}void AddLine(object s,RoutedEventArgs e){_lines.Add(new InvoiceLine{VatRate=_current.IsSmallBusinessSnapshot?0m:19m});UpdateTotals();}void RemoveLine(object s,RoutedEventArgs e){if(LineGrid.SelectedItem is InvoiceLine l&&_lines.Count>1)_lines.Remove(l);UpdateTotals();}void LineChanged(object s,EventArgs e){LineGrid.CommitEdit();UpdateTotals();}void UpdateTotals(){if(_current.IsSmallBusinessSnapshot)foreach(var line in _lines)line.VatRate=0m;var n=_lines.Sum(x=>x.NetAmount);var v=_lines.Sum(x=>x.VatAmount);NetText.Text=$"Netto: {n:N2} €";VatText.Text=$"Umsatzsteuer: {v:N2} €";GrossText.Text=$"Gesamt: {n+v:N2} €";LineGrid.Items.Refresh();}
 bool Validate(){if(CustomerBox.SelectedItem is not CustomerChoice){MessageBox.Show("Bitte einen Kunden auswählen.");return false;}if(ValidUntilBox.SelectedDate<OfferDateBox.SelectedDate){MessageBox.Show("Das Gültigkeitsdatum darf nicht vor dem Angebotsdatum liegen.");return false;}if(_lines.Any(x=>string.IsNullOrWhiteSpace(x.Description)||x.Quantity<=0||x.UnitPrice<0)){MessageBox.Show("Bitte die Positionen prüfen.");return false;}return true;}void ReadForm(){var c=(CustomerChoice)CustomerBox.SelectedItem;_current.CustomerId=c.Id;_current.CustomerNumber=c.CustomerNumber;_current.CustomerName=c.DisplayName;_current.OfferDate=OfferDateBox.SelectedDate??DateTime.Today;_current.ValidUntil=ValidUntilBox.SelectedDate??DateTime.Today.AddDays(14);_current.IntroText=IntroBox.Text.Trim();_current.ClosingText=ClosingBox.Text.Trim();if(_current.IsSmallBusinessSnapshot)foreach(var line in _lines)line.VatRate=0m;_current.Lines=_lines.ToList();}
 void SaveDraft(object s,RoutedEventArgs e){if(!Validate())return;ReadForm();_service.SaveDraft(_store,_current);RefreshList();LoadForm(_current);}void Finalize(object s,RoutedEventArgs e){if(!Validate())return;ReadForm();var preview=_service.Preview(_store,_current.OfferDate);var c=(CustomerChoice)CustomerBox.SelectedItem;var check=new OfferFinalizationCheckWindow(_current,c.AddressSnapshot,preview){Owner=Window.GetWindow(this)};if(check.ShowDialog()!=true)return;_service.Finalize(_store,_current,_invoiceService.LoadCompanySnapshot(),c.AddressSnapshot);RefreshNumberingUi();RefreshList();LoadForm(_current);}
 InvoiceDraft AsInvoiceDraft()=>new(){InvoiceNumber=_current.OfferNumber,CustomerId=_current.CustomerId,CustomerNumber=_current.CustomerNumber,CustomerName=_current.CustomerName,CustomerAddressSnapshot=_current.CustomerAddressSnapshot,CompanySnapshot=_current.CompanySnapshot,InvoiceDate=_current.OfferDate,ServiceDate=_current.OfferDate,PaymentTermDays=(_current.ValidUntil-_current.OfferDate).Days,IntroText=_current.IntroText,ClosingText=$"Gültig bis {_current.ValidUntil:dd.MM.yyyy}. {_current.ClosingText}",Status=_current.Status=="Abgelehnt"?"Storniert":"Abgeschlossen",Lines=_current.Lines};
 void Preview(object s,RoutedEventArgs e){new OfferPreviewWindow(Clone(_current)){Owner=Window.GetWindow(this)}.ShowDialog();}void Accept(object s,RoutedEventArgs e){_service.SetStatus(_store,_current,"Angenommen");RefreshList();LoadForm(_current);}void Reject(object s,RoutedEventArgs e){_service.SetStatus(_store,_current,"Abgelehnt");RefreshList();LoadForm(_current);}
 void CreateInvoice(object s,RoutedEventArgs e){if(MessageBox.Show("Aus diesem Angebot einen neuen Rechnungsentwurf erstellen?","Übernahme",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;var i=new InvoiceDraft{CustomerId=_current.CustomerId,CustomerNumber=_current.CustomerNumber,CustomerName=_current.CustomerName,InvoiceDate=DateTime.Today,ServiceDate=DateTime.Today,IntroText=$"Übernommen aus Angebot {_current.OfferNumber}.",ClosingText="Bitte überweisen Sie den Rechnungsbetrag innerhalb der angegebenen Zahlungsfrist.",Status="Entwurf",TaxModeSnapshot=_current.TaxModeSnapshot,SmallBusinessNoticeSnapshot=_current.SmallBusinessNoticeSnapshot,ShowLogoSnapshot=_current.ShowLogoSnapshot,LogoPngBase64Snapshot=_current.LogoPngBase64Snapshot,HeaderLine1Snapshot=_current.HeaderLine1Snapshot,HeaderLine2Snapshot=_current.HeaderLine2Snapshot,HeaderLine3Snapshot=_current.HeaderLine3Snapshot,HeaderLine4Snapshot=_current.HeaderLine4Snapshot,Lines=_current.Lines.Select(x=>new InvoiceLine{Description=x.Description,Quantity=x.Quantity,Unit=x.Unit,UnitPrice=x.UnitPrice,VatRate=x.VatRate,DiscountPercent=x.DiscountPercent}).ToList()};_invoiceService.SaveDraft(_invoices,i);_service.LinkInvoice(_store,_current,i.Id);RefreshList();LoadForm(_current);MessageBox.Show($"Rechnungsentwurf {i.DraftId} wurde erstellt.","Übernahme erfolgreich",MessageBoxButton.OK,MessageBoxImage.Information);}
}
